  function playAdminChime(){if(!adminSoundEnabled||!adminAudio||adminAudio.state!=='running')return;[0,0.18].forEach(function(delay,index){var oscillator=adminAudio.createOscillator(),gain=adminAudio.createGain(),start=adminAudio.currentTime+delay;oscillator.frequency.value=index?880:660;gain.gain.setValueAtTime(0,start);gain.gain.linearRampToValueAtTime(0.12,start+0.02);gain.gain.exponentialRampToValueAtTime(0.001,start+0.18);oscillator.connect(gain);gain.connect(adminAudio.destination);oscillator.start(start);oscillator.stop(start+0.2)})}
  function enableAdminSound(){var Audio=window.AudioContext||window.webkitAudioContext;if(!Audio){toast('Звук не поддерживается этим браузером');return}if(adminSoundEnabled){adminSoundEnabled=false;renderAdminOrderList(document.getElementById('profileContent'));return}try{adminAudio=adminAudio||new Audio();adminAudio.resume().then(function(){adminSoundEnabled=adminAudio.state==='running';if(adminSoundEnabled)playAdminChime();else toast('Разрешите звук в настройках браузера');renderAdminOrderList(document.getElementById('profileContent'))}).catch(function(){toast('Не удалось включить звук')})}catch(e){toast('Не удалось включить звук')}}
