  function allowStaffMessages(){var button=document.getElementById('allowStaffMessages');if(!window.vkBridge||typeof window.vkBridge.send!=='function'){toast('Откройте приложение внутри VK');return}staffMessagesBusy=true;if(button){button.disabled=true;button.textContent='Проверяем разрешение…'}window.vkBridge.send('VKWebAppAllowMessagesFromGroup',{group_id:242422490}).then(function(){markCommunityMessagePermission('allowed');staffMessagesChecked=true;staffMessagesEnabled=true;toast(staffMessagesEnabled?'Сообщения от сообщества разрешены ✓':'VK не подтвердил разрешение — проверьте системный запрос VK')}).catch(function(){markCommunityMessagePermission('not-allowed');staffMessagesChecked=true;staffMessagesEnabled=false;toast('VK не разрешил сообщения. Проверьте разрешения сообщества.')}).finally(function(){staffMessagesBusy=false;var current=document.getElementById('allowStaffMessages');if(current){current.disabled=false;current.classList.toggle('is-enabled',staffMessagesEnabled);current.classList.toggle('needs-permission',staffMessagesChecked&&!staffMessagesEnabled);current.textContent=staffMessagesEnabled?'Сообщения VK включены ✓':(staffMessagesChecked?'Разрешение не подтверждено · повторить':'Разрешить сообщения VK')}})}

  function setOrderIntakeUi(){var paused=!acceptingOrders,banner=document.getElementById('orderIntakeBanner'),checkout=document.getElementById('orderIntakeCheckout'),submit=document.querySelector('#checkoutForm [type="submit"]'),toggle=document.getElementById('toggleOrderIntake'),label=document.querySelector('.intake-admin-state');if(banner)banner.hidden=!paused;if(checkout)checkout.hidden=!paused;if(submit)submit.disabled=paused;if(label)label.textContent=paused?'Приём заявок приостановлен':'Приём заявок включён';if(toggle){toggle.disabled=orderIntakeBusy;toggle.classList.toggle('intake-paused',paused);toggle.textContent=orderIntakeBusy?'Сохраняем…':(paused?'Возобновить приём заявок':'Временно остановить приём')}}
  async function refreshOrderIntake(admin){var base=backendBaseUrl();if(!base||admin)return;try{var response=await fetch(base+'/health',{cache:'no-store'}),data=await response.json();if(!response.ok||typeof data.acceptingOrders!=='boolean')return;acceptingOrders=data.acceptingOrders;setOrderIntakeUi()}catch(error){/* Keep the last known state; the server still enforces the setting. */}}
  async function toggleOrderIntake(){if(orderIntakeBusy)return;var base=backendBaseUrl();if(!base){toast('Сервер не подключён');return}orderIntakeBusy=true;setOrderIntakeUi();try{var response=await fetch(base+'/admin/orders/SAKURA-SETTING-ORDER-INTAKE/status',{method:'PATCH',headers:vkAuthorizationHeaders({'content-type':'application/json'}),body:JSON.stringify({acceptingOrders:!acceptingOrders})}),data={};try{data=await response.json()}catch(error){}if(!response.ok||!data.ok)throw new Error('intake_setting_failed');acceptingOrders=data.acceptingOrders;toast(acceptingOrders?'Приём заявок возобновлён':'Новые заявки временно остановлены')}catch(error){toast('Не удалось изменить приём заявок. Проверьте соединение и обновите экран.')}finally{orderIntakeBusy=false;setOrderIntakeUi()}}

